// Runs the Wasm backend in a real browser (Chromium via playwright):
//   1. the in-process host: fixtures generated by the JavaScript build of the
//      compiler (browser_probe.bc.js), compiled through the promise API and
//      checked against the reference, in the page;
//   2. a real model generated by the native compiler (artifacts exported by
//      `loop_wasm_pt2 --export=DIR`) instantiated and run in the page, twice on
//      one instance with a dirty workspace, outputs compared byte for byte with
//      the node run's;
//   3. the deployment limits: synchronous compilation of the model on the main
//      thread, and a Content-Security-Policy without 'wasm-unsafe-eval'.
//
// usage: node scripts/wasm-browser-check.mjs <browser_probe.bc.js> <export-dir>
// Set PLAYWRIGHT_BROWSERS_PATH to the playwright browser cache.
import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "@playwright/test";

const [probe, dir] = process.argv.slice(2);
if (!probe || !dir) {
  console.error("usage: wasm-browser-check.mjs <browser_probe.bc.js> <export-dir>");
  process.exit(2);
}

const driver = `
const imports = { math: { exp: Math.exp, log: Math.log, sin: Math.sin, cos: Math.cos } };
const get = async (f) => new Uint8Array(await (await fetch("/model/" + f)).arrayBuffer());
window.syncCompile = async () => {
  const bytes = await get("model.wasm");
  try { new WebAssembly.Module(bytes); return "main-thread synchronous compile accepted"; }
  catch (e) { return "main-thread synchronous compile refused: " + e.name; }
};
window.runModel = async () => {
  const [wasm, weights, inputs, template, expected] = await Promise.all(
    ["model.wasm", "weights.bin", "inputs.bin", "outputs.template", "outputs.bin"].map(get));
  const pl = JSON.parse(new TextDecoder().decode(await get("placement.json")));
  let t = performance.now();
  let instance;
  try { ({ instance } = await WebAssembly.instantiate(wasm, imports)); }
  catch (e) { return { ok: false, stage: "instantiate", error: String(e) }; }
  const compileMs = performance.now() - t;
  const mem = new Uint8Array(instance.exports.memory.buffer);
  mem.set(weights, pl.weights); mem.set(inputs, pl.inputs);
  const run = () => {
    mem.fill(0xAB, pl.workspace, pl.workspace + pl.workspaceBytes);
    mem.set(template, pl.outputs);
    const t0 = performance.now();
    const rc = instance.exports.model_run(pl.weights, pl.inputs, pl.workspace, pl.outputs);
    const ms = performance.now() - t0;
    const out = mem.subarray(pl.outputs, pl.outputs + pl.outputsBytes);
    let same = out.length === expected.length;
    for (let i = 0; same && i < out.length; i++) if (out[i] !== expected[i]) same = false;
    return { rc, ms, same };
  };
  const first = run(), second = run();
  return { ok: first.rc === 0 && first.same && second.rc === 0 && second.same,
           compileMs, firstMs: first.ms, warmMs: second.ms,
           memoryBytes: instance.exports.memory.buffer.byteLength, identity: pl.identity };
};`;

const page = (name) => `<!doctype html><meta charset=utf-8><title>${name}</title>
<script src="/probe.js"></script><script src="/driver.js"></script>`;

function serve(csp) {
  const server = http.createServer((req, res) => {
    const url = req.url.split("?")[0];
    const headers = csp ? { "Content-Security-Policy": csp } : {};
    if (url === "/") { res.writeHead(200, { ...headers, "Content-Type": "text/html" }); res.end(page("wasm")); }
    else if (url === "/probe.js") { res.writeHead(200, { "Content-Type": "text/javascript" }); res.end(fs.readFileSync(probe)); }
    else if (url === "/driver.js") { res.writeHead(200, { "Content-Type": "text/javascript" }); res.end(driver); }
    else if (url.startsWith("/model/")) {
      const f = path.join(dir, path.basename(url));
      if (fs.existsSync(f)) { res.writeHead(200, { "Content-Type": "application/octet-stream" }); res.end(fs.readFileSync(f)); }
      else { res.writeHead(404); res.end(); }
    } else { res.writeHead(404); res.end(); }
  });
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(server)));
}

let failures = 0;
const expect = (cond, what) => { console.log((cond ? "ok   " : "FAIL ") + what); if (!cond) failures++; };

async function session(csp, body) {
  const server = await serve(csp);
  const browser = await chromium.launch();
  try {
    const p = await browser.newPage();
    const errors = [];
    p.on("pageerror", (e) => errors.push(String(e)));
    await p.goto(`http://127.0.0.1:${server.address().port}/`);
    return await body(p, browser, errors);
  } finally { await browser.close(); server.close(); }
}

// 1-3a. Allowed policy: Wasm may compile, nothing may eval.
const allowed = "default-src 'self'; script-src 'self' 'wasm-unsafe-eval'";
await session(allowed, async (p, browser, errors) => {
  console.log("engine: Chromium " + browser.version());
  await p.waitForFunction(() => window.__wasm_probe !== undefined, null, { timeout: 120000 });
  const lines = (await p.evaluate(() => window.__wasm_probe)).trim().split("\n");
  for (const l of lines) console.log("  probe: " + l);
  expect(lines.length === 4 && lines.every((l) => l.includes("identical to the reference")),
         "fixtures generated and run in the browser match the reference");
  expect(errors.length === 0, "no page errors under CSP script-src 'self' 'wasm-unsafe-eval'");
  const sync = await p.evaluate(() => window.syncCompile());
  console.log("  " + sync);
  const r = await p.evaluate(() => window.runModel());
  console.log("  model: " + JSON.stringify(r));
  expect(r.ok, "real model: two runs on one instance, outputs byte-identical to node's");
});

// 3b. A policy without 'wasm-unsafe-eval' must refuse, as a typed failure.
await session("default-src 'self'; script-src 'self'", async (p) => {
  await p.waitForFunction(() => window.__wasm_probe !== undefined, null, { timeout: 120000 });
  const text = await p.evaluate(() => window.__wasm_probe);
  console.log("  probe under a strict CSP: " + text.split("\n")[0]);
  expect(text.includes("prepare failed") && text.includes("rejected the module"),
         "without 'wasm-unsafe-eval' preparation fails with a typed Wasm_compile error");
});

process.exit(failures ? 1 : 0);
